-- Dwarka Tourism & Pilgrimage Guide Database Schema
-- Created for XAMPP / localhost

CREATE DATABASE IF NOT EXISTS `dwarka_guide` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `dwarka_guide`;

-- 1. Places Table (Temples and Tourist Spots)
DROP TABLE IF EXISTS `places`;
CREATE TABLE `places` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `name_gu` VARCHAR(255) NOT NULL,
    `name_en` VARCHAR(255) NOT NULL,
    `category` ENUM('temple', 'beach', 'nature', 'historical', 'bridge') NOT NULL DEFAULT 'temple',
    `location_type` ENUM('in_dwarka', 'nearby') NOT NULL DEFAULT 'in_dwarka',
    `deity_gu` VARCHAR(255) NULL,
    `timings` VARCHAR(255) DEFAULT 'સવારે ૬:૦૦ થી રાત્રે ૯:૦૦',
    `entry_fee` VARCHAR(100) DEFAULT 'મફત (Free)',
    `distance_km` VARCHAR(100) DEFAULT 'શહેરમાં',
    `image_url` VARCHAR(500) NULL,
    `short_desc` TEXT NOT NULL,
    `full_desc` LONGTEXT NOT NULL,
    `highlights` TEXT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2. Itineraries Table (Tour Schedules)
DROP TABLE IF EXISTS `itineraries`;
CREATE TABLE `itineraries` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `plan_days` INT NOT NULL, -- 1, 2, or 3 days
    `day_number` INT NOT NULL,
    `time_slot` VARCHAR(100) NOT NULL, -- 'સવાર (Morning)', 'બપોર (Afternoon)', 'સાંજ (Evening)'
    `title_gu` VARCHAR(255) NOT NULL,
    `description_gu` TEXT NOT NULL,
    `spots_covered` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 3. Temple Aarti Timings
DROP TABLE IF EXISTS `aarti_timings`;
CREATE TABLE `aarti_timings` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `aarti_name_gu` VARCHAR(255) NOT NULL,
    `time_str` VARCHAR(100) NOT NULL,
    `significance_gu` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 4. Budget Standards (Rates for Hotels, Gujarati Food, Transport)
DROP TABLE IF EXISTS `budget_rates`;
CREATE TABLE `budget_rates` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `category` VARCHAR(100) NOT NULL, -- 'stay', 'food', 'transport'
    `tier` VARCHAR(100) NOT NULL, -- 'budget', 'normal', 'deluxe'
    `title_gu` VARCHAR(255) NOT NULL,
    `approx_price` INT NOT NULL, -- in INR
    `unit_gu` VARCHAR(100) NOT NULL, -- 'પ્રતિ રાત્રિ', 'પ્રતિ થાળી', 'પ્રતિ દિવસ'
    `details_gu` TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 5. History Milestones
DROP TABLE IF EXISTS `history_timeline`;
CREATE TABLE `history_timeline` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `era_gu` VARCHAR(100) NOT NULL,
    `title_gu` VARCHAR(255) NOT NULL,
    `description_gu` TEXT NOT NULL,
    `order_seq` INT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 6. User Reviews & Inquiries
DROP TABLE IF EXISTS `reviews`;
CREATE TABLE `reviews` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `user_name` VARCHAR(150) NOT NULL,
    `user_city` VARCHAR(150) NOT NULL,
    `rating` INT DEFAULT 5,
    `user_comment` TEXT NOT NULL,
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ==========================================
-- SEED DATA INSERTION (સંપૂર્ણ વિગતો)
-- ==========================================

-- A. Places (દ્વારકા અને આજુબાજુના જોવાલાયક સ્થળો)
INSERT INTO `places` (`name_gu`, `name_en`, `category`, `location_type`, `deity_gu`, `timings`, `entry_fee`, `distance_km`, `image_url`, `short_desc`, `full_desc`, `highlights`) VALUES
('શ્રી દ્વારકાધીશ જગત મંદિર', 'Shree Dwarkadhish Jagat Mandir', 'temple', 'in_dwarka', 'ભગવાન શ્રીકૃષ્ણ (રાજાધિરાજ)', 'સવારે ૬:૩૦ થી બપોરે ૧:૦૦ અને સાંજે ૫:૦૦ થી રાત્રે ૯:૩૦', 'મફત (Free)', 'દ્વારકા શહેર કેન્દ્ર', 'images/dwarkadhish.jpg', 'હિન્દુ ધર્મના પવિત્ર ચાર ધામ પૈકીનું પશ્ચિમ ધામ, ૭૨ સ્તંભો પર નિર્મિત ભવ્ય ૫ માળનું પૌરાણિક મંદિર.', 'દ્વારકાધીશ મંદિરને જગત મંદિર તરીકે પણ ઓળખવામાં આવે છે. આ મંદિર અંદાજે ૨૫૦૦ વર્ષથી પણ વધુ જૂનું માનવામાં આવે છે, જેનું મૂળ નિર્માણ ભગવાન શ્રીકૃષ્ણના પ્રપૌત્ર વજ્રનાભ દ્વારા કરવામાં આવ્યું હતું. મંદિરના શિખર પર ૫૨ ગજની ભવ્ય ધજા ફરકે છે, જે દિવસમાં ૬ વખત ચઢાવવામાં આવે છે. મંદિરમાં બે મુખ્ય પ્રવેશદ્વાર છે: સ્વર્ગ દ્વાર (ગોમતી ઘાટ તરફથી ૫૬ પગથિયાં ચઢીને) અને મોક્ષ દ્વાર (બજાર તરફ).', '૫૨ ગજની ધજા, સ્વર્ગ દ્વાર, મોક્ષ દ્વાર, ચાંદીના સિંહાસન પર બિરાજમાન ચતુર્ભુજ શ્યામ મૂર્તિ'),

('ગોમતી ઘાટ અને સંગમ', 'Gomti Ghat and Sangam', 'nature', 'in_dwarka', 'પવિત્ર ગોમતી નદી અને અરબી સમુદ્ર', 'સૂર્યોદય થી સૂર્યાસ્ત', 'મફત (Free)', 'જગત મંદિરની પાછળ (૫૬ પગથિયાં નીચે)', 'images/gomti_ghat.jpg', 'ગોમતી નદી અને અરબી સમુદ્રનો પવિત્ર સંગમ, જ્યાં સ્નાન કરવાનું મોક્ષદાયી મહત્વ છે.', 'ગોમતી ઘાટ દ્વારકાધીશ મંદિરની બિલકુલ સમીપ આવેલો છે. અહીં ગોમતી નદી અરબી સમુદ્રને મળે છે. પુરાણો અનુસાર ગોમતી સ્નાનથી તમામ પાપોમાંથી મુક્તિ મળે છે. ઘાટ પર ભક્તો માટે સ્નાન કરવાની સુંદર વ્યવસ્થા છે, અહીંથી બોટિંગ દ્વારા સમુદ્ર સંગમ સુધી પણ જઈ શકાય છે.', 'પવિત્ર સ્નાન, સાંજની મહા આરતી, નૌકાવિહાર (Boating), ચક્રતીર્થ'),

('સુદામા સેતુ', 'Sudama Setu', 'bridge', 'in_dwarka', 'શ્રીકૃષ્ણ-સુદામા મૈત્રી સ્મારક', 'સવારે ૭:૦૦ થી સાંજે ૭:૦૦', '₹૫૦ પ્રતિ વ્યક્તિ', 'ગોમતી ઘાટ પાસે', 'images/sudama_setu.jpg', 'ગોમતી નદી પર બનેલો આધુનિક કેબલ સસ્પેન્શન બ્રિજ, જે પંચનદ તીર્થ અને સમુદ્રતટ તરફ લઈ જાય છે.', 'સુદામા સેતુ ગોમતી નદીના બન્ને કાંઠાને જોડતો આકર્ષક કેબલ બ્રિજ છે. આ પુલ પરથી જગત મંદિર અને સમુદ્રનો અદ્ભુત નજારો જોવા મળે છે. પુલ પાર કરીને સામે કાંઠે આવેલા પંચનદ તીર્થ (પાંડવો દ્વારા ખોદાયેલા ૫ મીઠા પાણીના કૂવા) અને દરિયાકિનારે જઈ શકાય છે.', 'કેબલ સસ્પેન્શન આર્કિટેક્ચર, અદ્ભુત ફોટોગ્રાફી પોઈન્ટ, કેમલ રાઈડ અને બીચ એક્ટિવિટી'),

('ભડકેશ્વર મહાદેવ મંદિર', 'Bhadkeshwar Mahadev Temple', 'temple', 'in_dwarka', 'ભગવાન શિવ (સ્વયંભૂ શિવલિંગ)', 'સવારે ૬:૦૦ થી સાંજે ૭:૩૦', 'મફત (Free)', 'દ્વારકા શહેરથી ૨ કિ.મી.', 'images/bhadkeshwar.jpg', 'અરબી સમુદ્રની વચ્ચે એક નાની ટેકરી પર સ્થિત અતિ સુંદર પ્રાચીન શિવ મંદિર.', 'ભડકેશ્વર મહાદેવ મંદિર દરિયાના મોજાં વચ્ચે ટેકરી પર આવેલું છે. ચોમાસામાં ભરતી સમયે સમુદ્રનું પાણી ખુદ શિવલિંગનો જળાભિષેક કરે છે. અહીંથી સાંજના સમયે સૂર્યાસ્ત (Sunset) જોવાનો લહાવો અનિવાર્ય છે.', 'દરિયા વચ્ચેનું રમણીય સ્થળ, સનસેટ વ્યૂ, સ્વયંભૂ શિવલિંગ'),

('દ્વારકા બીચ અને દીવાદાંડી (લાઈટહાઉસ)', 'Dwarka Beach & Lighthouse', 'beach', 'in_dwarka', 'પ્રકૃતિ અને સાગર દર્શન', 'લાઈટહાઉસ: સાંજે ૪:૦૦ થી ૬:૦૦', 'લાઈટહાઉસ: ₹૧૫ - ₹૨૦', 'દ્વારકાથી ૧.૫ કિ.મી.', 'images/lighthouse.jpg', 'અરબી સમુદ્રનો શાંત કિનારો અને ૪૩ મીટર ઊંચી ઐતિહાસિક દીવાદાંડી.', 'દ્વારકાનો દરિયાકિનારો શાંત અને રમણીય છે. અહીં આવેલી દીવાદાંડીની ટોચ પર ચઢીને સમગ્ર દ્વારકા શહેર, અરબી સમુદ્ર અને જગત મંદિરનું ૩૬૦ ડિગ્રી અદ્ભુત વિહંગાવલોકન કરી શકાય છે.', 'વિહંગાવલોકન, ઠંડી સાગરી લહેરો, સાંજના સમયે પરિવાર સાથે બેસવા માટે ઉત્તમ સ્થળ'),

('ગીતા મંદિર અને શારદા પીઠ', 'Gita Mandir and Sharda Peeth', 'temple', 'in_dwarka', 'શ્રીમદ્ ભગવદ્ ગીતા & આદિ શંકરાચાર્ય', 'સવારે ૭:૦૦ થી રાત્રે ૮:૦૦', 'મફત (Free)', 'જગત મંદિર પાસે', 'images/gita_mandir.jpg', 'બિરલા પરિવાર દ્વારા સંગેમરમરથી નિર્મિત ગીતા મંદિર અને આદિ શંકરાચાર્ય દ્વારા સ્થાપિત શારદા પીઠ.', 'ગીતા મંદિરની આરસપહાણની દીવાલો પર સંપૂર્ણ શ્રીમદ્ ભગવદ્ ગીતાના ૧૮ અધ્યાય અને ૭૦૦ શ્લોક કોતરેલા છે. પાસે જ આદિ શંકરાચાર્ય દ્વારા ભારતના ચાર ખૂણે સ્થાપેલા ચાર મઠો પૈકીનો પશ્ચિમ મઠ શારદા પીઠ આવેલો છે.', 'ગીતાજીના શ્લોકોનું કોતરણીકામ, આધ્યાત્મિક શાંતિ, ઐતિહાસિક શારદા મઠ'),

('બેટ દ્વારકા (શંખોદ્ધાર બેટ)', 'Beyt Dwarka', 'temple', 'nearby', 'ભગવાન શ્રીકૃષ્ણ (રાજાધિરાજ - રહેઠાણ મહેલ)', 'સવારે ૬:૩૦ થી બપોરે ૧૨:૦૦ અને સાંજે ૫:૦૦ થી ૯:૦૦', 'મફત (Free)', 'દ્વારકાથી ૩૨ કિ.મી. + બોટ/બ્રિજ', 'images/beyt_dwarka.jpg', 'ભગવાન શ્રીકૃષ્ણનું પ્રાચીન રહેઠાણ અને જ્યાં સુદામાજી તાંદુલ (પૌંઆ) લઈને મળવા આવ્યા હતા તે પવિત્ર બેટ.', 'બેટ દ્વારકા એક ટાપુ છે જ્યાં શ્રીકૃષ્ણનો મુખ્ય નિવાસ માનવામાં આવે છે. અહીં શ્રીકૃષ્ણ, રુક્ષ્મણીજી, સત્યભામા અને જાંબવતીના સુંદર મંદિરો આવેલા છે. હવે નવનિર્મિત સુદર્શન સેતુ (ભારતનો સૌથી લાંબો કેબલ બ્રિજ) બની જવાથી ઓખાથી સીધા રોડ માર્ગે કે ફેરી બોટ દ્વારા પહોંચી શકાય છે.', 'સુદર્શન સેતુ બ્રિજ, સુદામા-કૃષ્ણ મિલન સ્થળ, શંખની બનાવટોની ખરીદી, સમુદ્રી સૌંદર્ય'),

('શ્રી નાગેશ્વર જ્યોતિર્લિંગ', 'Shree Nageshwar Jyotirlinga', 'temple', 'nearby', 'ભગવાન શિવ (૧૨ જ્યોતિર્લિંગ પૈકીનું દારૂકાવન જ્યોતિર્લિંગ)', 'સવારે ૬:૦૦ થી રાત્રે ૯:૦૦', 'મફત (Free)', 'દ્વારકાથી ૧૬ કિ.મી.', 'images/nageshwar.jpg', 'હિન્દુ ધર્મના અત્યંત પવિત્ર ૧૨ જ્યોતિર્લિંગ પૈકીનું એક દિવ્ય જ્યોતિર્લિંગ અને ભગવાન શિવની ૮૨ ફૂટ ઊંચી પ્રતિમા.', 'શિવપુરાણમાં વર્ણવેલા ૧૨ જ્યોતિર્લિંગોમાં નાગેશ્વર જ્યોતિર્લિંગ પ્રથમ ગણાતા દારૂકાવન વિસ્તારમાં આવેલું છે. મંદિરના પરિસરમાં ભગવાન શિવજીની ૮૨ ફૂટ ઊંચી ભવ્ય ધ્યાનસ્થ મૂર્તિ દેશ-વિદેશના યાત્રાળુઓનું મુખ્ય આકર્ષણ છે.', '૧૨ જ્યોતિર્લિંગ દર્શન, ૮૨ ફૂટની વિશાળ શિવ પ્રતિમા, જળાભિષેક પૂજા'),

('શિવરાજપુર બ્લુ ફ્લેગ બીચ', 'Shivrajpur Blue Flag Beach', 'beach', 'nearby', 'પ્રકૃતિ અને સાહસિક વોટર સ્પોર્ટ્સ', 'સવારે ૮:૦૦ થી સાંજે ૭:૦૦', '₹૩૦ પ્રતિ વ્યક્તિ (એન્ટ્રી)', 'દ્વારકાથી ૧૨ કિ.મી.', 'images/shivrajpur.jpg', 'આંતરરાષ્ટ્રીય કક્ષાનું "Blue Flag" પ્રમાણપત્ર ધરાવતો ગુજરાતનો સૌથી સ્વચ્છ અને સુંદર સફેદ રેતીનો દરિયાકિનારો.', 'શિવરાજપુર બીચ ભારત સરકાર અને યુનેસ્કો દ્વારા પ્રમાણિત બ્લુ ફ્લેગ બીચ છે. અહીંનું પાણી કાચ જેવું પારદર્શક અને રેતી સોનેરી-સફેદ છે. અહીં સ્કૂબા ડાઇવિંગ, પેરાસેઇલિંગ, સ્નોર્કલિંગ, સ્પીડ બોટિંગ જેવી વોટર સ્પોર્ટ્સ ઉપલબ્ધ છે.', 'આંતરરાષ્ટ્રીય બ્લુ ફ્લેગ સર્ટિફિકેશન, સ્કૂબા ડાઇવિંગ, વોટર રાઈડ્સ, સ્વિમિંગ માટે સુરક્ષિત કિનારો'),

('શ્રી રુક્ષ્મણી દેવી મંદિર', 'Shree Rukmini Devi Temple', 'temple', 'nearby', 'માતા રુક્ષ્મણીજી (શ્રીકૃષ્ણના પટ્ટરાણી)', 'સવારે ૬:૦૦ થી રાત્રે ૮:૩૦', 'મફત (Free)', 'દ્વારકાથી ૨.૫ કિ.મી.', 'images/rukmini_temple.jpg', 'દ્વારકાધીશ મંદિરથી અલગ ૨.૫ કિમી દૂર સ્થિત ૧૨મી સદીનું પ્રાચીન કલાત્મક મંદિર.', 'પૌરાણિક કથા મુજબ દુર્વાસા ઋષિના રથને ખેંચતી વખતે રુક્ષ્મણીજીને તરસ લાગતા શ્રીકૃષ્ણએ જમીનમાંથી ગંગાજી પ્રગટ કરી પાણી પાયું, જેનાથી દુર્વાસા ઋષિએ ક્રોધિત થઈને અલગ રહેવાનો શ્રાપ આપ્યો હતો. તેથી રુક્ષ્મણીજીનું મંદિર મુખ્ય મંદિરથી અલગ છે. આ મંદિર પર અદ્ભુત શિલ્પકળા અને હાથીઓની કોતરણી છે.', 'દુર્વાસા ઋષિનો પૌરાણિક શ્રાપ અને જળદાન કથા, બેજોડ પથ્થર શિલ્પકળા'),

('ગોપી તળાવ', 'Gopi Talav', 'nature', 'nearby', 'શ્રીકૃષ્ણ અને વ્રજની ગોપીઓ', 'સવારે ૬:૦૦ થી સાંજે ૭:૦૦', 'મફત (Free)', 'દ્વારકાથી ૨૧ કિ.મી.', 'images/gopi_talav.jpg', 'જ્યાં શ્રીકૃષ્ણ સાથે રાસલીલા બાદ ગોપીઓ પવિત્ર જમીનમાં સમાઈ ગઈ હતી તે તળાવ, જ્યાંથી પીળી માટી (ગોપી ચંદન) મળે છે.', 'માન્યતા મુજબ વ્રજની ગોપીઓ શ્રીકૃષ્ણને મળવા દ્વારકા આવી હતી અને અહીં રાસ રમ્યા બાદ ધરતીમાં સમાઈ ગઈ હતી. આ તળાવની માટી અત્યંત મુલાયમ અને પીળા રંગની છે જેને "ગોપી ચંદન" કહેવાય છે. વૈષ્ણવ ભક્તો આ ચંદનનું તિલક ધારણ કરે છે.', 'પવિત્ર ગોપી ચંદન, માછલીઓને ખોરાક આપવો, શાંત વાતાવરણ');

-- B. Temple Aarti Timings (દર્શન અને આરતી સમય)
INSERT INTO `aarti_timings` (`aarti_name_gu`, `time_str`, `significance_gu`) VALUES
('મંગળા આરતી (Mangla Aarti)', 'સવારે ૬:૩૦ વાગ્યે', 'પ્રભાત કાળે ભગવાનને જગાડીને કરવામાં આવતી પ્રથમ મંગલકારી દિવ્ય આરતી.'),
('શૃંગાર દર્શન & આરતી (Shringar Aarti)', 'સવારે ૭:૩૦ થી ૮:૦૦ વાગ્યે', 'ભગવાન શ્રીકૃષ્ણનું સિંહાસન પર પીતાંબર, મોરપીંછ અને સુવર્ણ આભૂષણો સાથે અલૌકિક શૃંગાર.'),
('રાજભોગ દર્શન & આરતી (Rajbhog Aarti)', 'બપોરે ૧૨:૦૦ થી ૧૨:૩૦ વાગ્યે', 'ઠાકોરજીને ૫૬ ભોગ અને રાજભોગ ધરાવીને કરવામાં આવતી ભવ્ય આરતી (૧:૦૦ વાગ્યે મંદિર મંગલ થાય છે).'),
('ઉત્થાપન દર્શન (Utthapan)', 'સાંજે ૫:૦૦ વાગ્યે', 'બપોરના વિશ્રામ બાદ સાંજે ભક્તો માટે પુનઃ મંદિરના કપાટ ખુલે છે.'),
('સંધ્યા આરતી (Sandhya Aarti)', 'સાંજે ૭:૩૦ થી ૭:૪૫ વાગ્યે', 'સૂર્યાસ્ત સમયે દીપમાળા પ્રગટાવીને થતી ભવ્ય આરતી અને શંખનાદ.'),
('શયન ભોગ & શયન આરતી (Shayan Aarti)', 'રાત્રે ૮:૩૦ થી ૯:૦૦ વાગ્યે', 'રાત્રિ ભોગ અર્પણ કર્યા બાદ ભગવાનના વિશ્રામ પૂર્વેની આરતી (૯:૩૦ વાગ્યે મંદિર મંગલ).');

-- C. Travel Itineraries (સમયપત્રક / ટૂર પ્લાન)
INSERT INTO `itineraries` (`plan_days`, `day_number`, `time_slot`, `title_gu`, `description_gu`, `spots_covered`) VALUES
(1, 1, 'સવાર (૦૬:૦૦ થી ૧૧:૦૦)', 'મંગળા આરતી, ગોમતી સ્નાન અને જગત મંદિર દર્શન', 'સવારે ૬:૦૦ વાગ્યે ગોમતી ઘાટ પર પવિત્ર સ્નાન કરી ૫૬ પગથિયાં ચઢી સ્વર્ગ દ્વારથી જગત મંદિરમાં પ્રવેશ કરો. મંગળા આરતી અને શૃંગાર દર્શનનો લાભ લો. બાદમાં સુદામા સેતુ અને પંચનદ તીર્થની મુલાકાત લો.', 'ગોમતી ઘાટ, જગત મંદિર, સુદામા સેતુ, પંચનદ તીર્થ'),
(1, 1, 'બપોર (૧૧:૩૦ થી ૦૪:૩૦)', 'બેટ દ્વારકા અને નાગેશ્વર જ્યોતિર્લિંગ યાત્રા', 'કાઠિયાવાડી/ગુજરાતી થાળી જમીને લોકલ ટેક્સી કે બસ દ્વારા નાગેશ્વર જ્યોતિર્લિંગ દર્શન માટે નીકળો. ત્યાંથી ઓખા પહોંચી સુદર્શન સેતુ દ્વારા બેટ દ્વારકા દર્શન કરો. રસ્તામાં ગોપી તળાવ પણ જઈ શકો છો.', 'નાગેશ્વર જ્યોતિર્લિંગ, બેટ દ્વારકા, ગોપી તળાવ'),
(1, 1, 'સાંજ (૦૫:૦૦ થી ૦૯:૦૦)', 'રુક્ષ્મણી મંદિર, ભડકેશ્વર મહાદેવ અને સંધ્યા આરતી', 'પરત દ્વારકા આવી રુક્ષ્મણી માતાજીના દર્શન કરો. ભડકેશ્વર મહાદેવ ખાતે દરિયા વચ્ચે સુંદર સૂર્યાસ્ત માણો. રાત્રે દ્વારકાધીશ મંદિરમાં સંધ્યા આરતીના દર્શન કરી સ્થાનિક બજારમાં ખરીદી કરો.', 'રુક્ષ્મણી મંદિર, ભડકેશ્વર મહાદેવ, દ્વારકા બજાર'),

(2, 1, 'દિવસ ૧: દ્વારકા નગરી દર્શન', 'ગોમતી ઘાટ, જગત મંદિર, ભડકેશ્વર અને દીવાદાંડી', 'પ્રથમ દિવસે સમગ્ર દ્વારકા શહેરના દર્શન: ગોમતી સ્નાન, જગત મંદિર દર્શન અને ધજા ચઢાવવાની વિધિ દર્શન, ગીતા મંદિર, શારદા પીઠ, બપોરે આરામ અને સાંજે ભડકેશ્વર મહાદેવ સનસેટ તથા લાઈટહાઉસ.', 'જગત મંદિર, ગોમતી ઘાટ, સુદામા સેતુ, ગીતા મંદિર, ભડકેશ્વર'),
(2, 2, 'દિવસ ૨: આસપાસના ધાર્મિક અને પ્રાકૃતિક તીર્થો', 'નાગેશ્વર, ગોપી તળાવ, બેટ દ્વારકા અને શિવરાજપુર બીચ', 'સવારે નાગેશ્વર જ્યોતિર્લિંગ દર્શન અને અભિષેક. ગોપી તળાવથી ગોપી ચંદન દર્શન. બેટ દ્વારકા શ્રીકૃષ્ણ નિવાસ દર્શન. બપોર પછી શિવરાજપુર બ્લુ ફ્લેગ બીચ પર પારદર્શક સાગરનો આનંદ અને વોટર સ્પોર્ટ્સ.', 'નાગેશ્વર, ગોપી તળાવ, બેટ દ્વારકા, સુદર્શન સેતુ, શિવરાજપુર બીચ'),

(3, 1, 'દિવસ ૧: આધ્યાત્મિક દ્વારકા અનુભૂતિ', 'મંગળા આરતી, ધ્વજારોહણ દર્શન અને પવિત્ર સ્નાન', 'પ્રથમ દિવસે પૂર્ણ શાંતિથી દ્વારકાધીશના તમામ દર્શન (મંગળા, શૃંગાર, રાજભોગ, સંધ્યા આરતી). ૫૨ ગજની ધજા ચઢાવવાનો ભક્તિભાવપૂર્વક ઉત્સવ જોવો. ગોમતી નૌકાવિહાર.', 'જગત મંદિર, ૫૨ ગજ ધ્વજા, ગોમતી સંગમ, સુદામા સેતુ'),
(3, 2, 'દિવસ ૨: પૌરાણિક કથા માર્ગ (બેટ દ્વારકા & જ્યોતિર્લિંગ)', 'સુદર્શન સેતુ, શંખોદ્ધાર બેટ, ગોપી તળાવ અને નાગેશ્વર', 'આખો દિવસ બેટ દ્વારકા ટાપુ અને આસપાસના તીર્થો માટે. સુદર્શન સેતુ બ્રિજ પર ફોટોગ્રાફી, બેટ દ્વારકા મંદિર, રુક્ષ્મણી મંદિર, ગોપી તળાવ અને ૧૨ જ્યોતિર્લિંગ પૈકી નાગેશ્વર દર્શન.', 'બેટ દ્વારકા, સુદર્શન સેતુ, ગોપી તળાવ, નાગેશ્વર, રુક્ષ્મણી મંદિર'),
(3, 3, 'દિવસ ૩: કુદરતી સૌંદર્ય અને વિદાય', 'શિવરાજપુર બીચ, સ્કૂબા ડાઇવિંગ અને સ્થાનિક ખરીદી', 'સવારે શિવરાજપુર બ્લુ ફ્લેગ બીચ પર સ્કૂબા ડાઇવિંગ / વોટર સ્પોર્ટ્સ. બપોરે દ્વારકાની પ્રખ્યાત પેંડા, પાપડ અને શંખ-છીપલાંની સ્થાનિક બજારમાંથી ખરીદી. સાંજે વિદાય.', 'શિવરાજપુર બ્લુ ફ્લેગ બીચ, સ્થાનિક બજાર, ખરીદી');

-- D. Budget Rates (હોટેલ, ગુજરાતી જમણવાર અને વાહન વ્યવહાર ખર્ચ)
INSERT INTO `budget_rates` (`category`, `tier`, `title_gu`, `approx_price`, `unit_gu`, `details_gu`) VALUES
('stay', 'budget', 'સામાન્ય ધર્મશાળા / આશ્રમ / અતિથિગૃહ', 500, 'પ્રતિ રૂમ / રાત્રિ', 'મંદિર નજીક આવેલી સમાજની ધર્મશાળાઓ, સ્વચ્છ રૂમ, ગરમ પાણી અને મૂળભૂત સુવિધાઓ (દા.ત. અખિલ ભારતીય લોહાણા મહાજન, મહેશ્વરી ભવન વગેરે).'),
('stay', 'normal', 'નોર્મલ બજેટ હોટેલ (AC / Non-AC)', 1200, 'પ્રતિ રૂમ / રાત્રિ', 'સામાન્ય બજેટ હોટેલ, ટીવી, એટેચ બાથરૂમ, લિફ્ટ, વાઈફાઈ અને રૂમ સર્વિસ સાથે સ્વચ્છ ફેમિલી રૂમ.'),
('stay', 'deluxe', 'પ્રીમિયમ / થ્રી-સ્ટાર હોટેલ & રિસોર્ટ', 2600, 'પ્રતિ રૂમ / રાત્રિ', 'લક્ઝરી હોટેલ, સી-વ્યૂ (સમુદ્ર દર્શન), સ્વિમિંગ પૂલ, મલ્ટી-કુઝિન રેસ્ટોરન્ટ અને પ્રીમિયમ સુવિધાઓ.'),

('food', 'budget', 'મંદિર અન્નક્ષેત્ર / સાદું ગુજરાતી ભોજન', 70, 'પ્રતિ થાળી', 'મંદિર સંચાલિત અન્નક્ષેત્ર અથવા સાદા ભોજનાલયમાં રોટલી, દાળ, ભાત, શાકનું પવિત્ર અને સાત્વિક ભોજન.'),
('food', 'normal', 'નોર્મલ ગુજરાતી / કાઠિયાવાડી અનલિમિટેડ થાળી', 130, 'પ્રતિ થાળી', 'દ્વારકાની પ્રખ્યાત કાઠિયાવાડી થાળી: ૨ શાક (સેવ ટમેટા, રિંગણા ઓળો કે બટેટા), રોટલી/ગરમાગરમ બાજરાના રોટલા, દાળ-ભાત, ગોળ, માખણ, મસાલા છાશ, પાપડ અને અથાણું.'),
('food', 'deluxe', 'પ્રીમિયમ ગુજરાતી ફિક્સ/સ્પેશિયલ થાળી & મિઠાઈ', 220, 'પ્રતિ થાળી', 'સ્પેશિયલ કાઠિયાવાડી થાળી + ફરસાણ (ઢોકળા/ખાંડવી), મીઠાઈ (શ્રીખંડ/ગુલાબ જાંબુ/સુખડી), પનીર શાક અને સ્પેશિયલ છાશ.'),

('transport', 'budget', 'લોકલ GSRTC બસ / શેરિંગ છકડો રિક્ષા', 150, 'પ્રતિ વ્યક્તિ / દિવસ', 'ઓખા જવા માટે લોકલ બસ કે શેરિંગ રિક્ષા, દ્વારકા લોકલ ફરવા માટે પગપાળા અથવા શેરિંગ વાહન.'),
('transport', 'normal', 'પ્રાઇવેટ ઓટો રિક્ષા (આખો દિવસ / સાઇટસીઇંગ)', 800, 'પ્રતિ રિક્ષા (૩-૪ વ્યક્તિ)', 'દ્વારકા લોકલ સાઇટસીઇંગ (ભડકેશ્વર, રુક્ષ્મણી મંદિર, ગોમતી ઘાટ) માટે આખો દિવસ રિક્ષા બુકિંગ.'),
('transport', 'deluxe', 'પ્રાઇવેટ AC ટેક્સી / કાર (દ્વારકા + બેટ દ્વારકા + નાગેશ્વર)', 2200, 'પ્રતિ કાર / દિવસ', 'સંપૂર્ણ આરામદાયક એસી કાર (Swift Dzire/Ertiga) જેમાં દ્વારકા, નાગેશ્વર, ગોપી તળાવ, બેટ દ્વારકા, શિવરાજપુર બીચ કવર થાય.');

-- E. History Timeline (દ્વારકાનો પૌરાણિક અને ઐતિહાસિક વારસો)
INSERT INTO `history_timeline` (`era_gu`, `title_gu`, `description_gu`, `order_seq`) VALUES
('દ્વાપર યુગ (આશરે ૫૦૦૦+ વર્ષ પૂર્વે)', 'ભગવાન શ્રીકૃષ્ણ દ્વારા સ્વર્ણ દ્વારકાનું નિર્માણ', 'મથુરાના રાજા કંસના વધ બાદ જરાસંધના વારંવારના આક્રમણોથી મથુરાવાસીઓને સુરક્ષિત કરવા શ્રીકૃષ્ણએ યાદવો સાથે સૌરાષ્ટ્રના પશ્ચિમ સમુદ્રકાંઠે પ્રસ્થાન કર્યું. દેવશિલ્પી વિશ્વકર્મા દ્વારા સમુદ્ર પાસેથી ૧૨ યોજન જમીન માંગી સોનાની અદ્ભુત નગરી "સ્વર્ણ દ્વારિકા" બનાવી, જેમાં સેંકડો ભવ્ય મહેલો, સુવર્ણ કિલ્લાઓ અને બગીચાઓ હતા.', 1),
('મહાભારત કાળ', 'યાદવ વંશ અને મોક્ષપુરી', 'દ્વારકા શ્રીકૃષ્ણના રાજ્યકાળ દરમિયાન ભારતના સૌથી સમૃદ્ધ અને શક્તિશાળી સામ્રાજ્ય તરીકે ઉભરી આવી. મહાભારતના ભીષણ યુદ્ધ બાદ ગાંધારીના શ્રાપ અને ઋષિઓના શાપને લીધે યાદવાસ્થળી સર્જાઈ.', 2),
('શ્રીકૃષ્ણ સ્વધામ ગમન બાદ', 'દ્વારકાનું સમુદ્રમાં જળમગ્ન થવું', 'ભગવાન શ્રીકૃષ્ણ ભાલકા તીર્થ (પ્રભાસ પાટણ) ખાતે સ્વધામ પધાર્યા બાદ અર્જુન દ્વારા યાદવ સ્ત્રી-બાળકોને સુરક્ષિત હસ્તિનાપુર લઈ જવાયા. ત્યારપછી તરત જ પ્રચંડ સુનામી અને દરિયાના મોજાં ઉછળ્યા અને ભવ્ય સ્વર્ણ દ્વારકા સમુદ્રના ગર્ભમાં સમાઈ ગઈ.', 3),
('પ્રાચીન કાળ (પ્રપૌત્ર વજ્રનાભ દ્વારા)', 'પ્રથમ જગત મંદિરનું નિર્માણ', 'શ્રીકૃષ્ણના પ્રપૌત્ર વજ્રનાભ દ્વારા ભગવાનના મૂળ નિવાસ સ્થાન (હરિ ગૃહ) પર પ્રથમ છત્ર/મંદિરનું નિર્માણ કરાયું, જે "જગત મંદિર" તરીકે ઓળખાયું.', 4),
('ઈ.સ. ૮મી સદી', 'આદિ શંકરાચાર્ય દ્વારા શારદા પીઠની સ્થાપના', 'જગતગુરુ આદિ શંકરાચાર્યજીએ સનાતન ધર્મના પુનરુત્થાન માટે ભારતના પશ્ચિમ ખૂણે દ્વારકામાં "શારદા પીઠ"ની સ્થાપના કરી, જેનાથી દ્વારકા ચાર ધામ પૈકીનું એક મુખ્ય ધામ બન્યું.', 5),
('ઈ.સ. ૧૬મી સદી અને પુનઃનિર્માણ', 'વર્તમાન ભવ્ય મંદિર સ્થાપત્ય', 'સમય જતાં વિવિધ આક્રમણો અને કુદરતી આપત્તિઓ વચ્ચે પણ ભક્તો અને રાજાઓએ મંદિરનું પુનઃનિર્માણ કર્યું. વર્તમાન મંદિર ચાલુક્ય શૈલી અને ૭૨ કલાત્મક સ્તંભો પર ચૂનાના પથ્થરોથી શોભી રહ્યું છે.', 6),
('આધુનિક યુગ (૧૯૮૩ થી ૨૦૨૪)', 'સમુદ્ર તળે સંશોધન (Underwater Archeology)', 'પ્રખ્યાત પુરાતત્વવિદ્ ડૉ. એસ. આર. રાવ (ડૉ. એસ.આર. રાવ) અને ભારતીય નેવી દ્વારા સમુદ્રના પેટાળમાં સંશોધન કરાયું, જેમાં પ્રાચીન કિલ્લાની દીવાલો, ૫૦૦૦ વર્ષ જૂના પથ્થરના લંગર (Anchors) અને વાસણો મળ્યા. ૨૦૨૪માં ભારતના વડાપ્રધાન શ્રી નરેન્દ્ર મોદીજીએ સમુદ્રના તળિયે સ્કૂબા ડાઇવિંગ કરી મોરપીંછ અર્પણ કરી પ્રાચીન દ્વારકાની પૂજા કરી હતી.', 7);

-- F. Sample Reviews & Feedback
INSERT INTO `reviews` (`user_name`, `user_city`, `rating`, `user_comment`) VALUES
('રમેશભાઈ પટેલ', 'અમદાવાદ', 5, 'દ્વારકામાં જગત મંદિરના દર્શન કરીને જીવન ધન્ય થઈ ગયું! ૫૨ ગજની ધજા અને ગોમતી ઘાટની સાંજ અદ્ભુત હતી. સામાન્ય હોટેલ અને ગુજરાતી થાળી ખૂબ સસ્તા અને સ્વાદિષ્ટ હતા.'),
('ભાવિક શાહ', 'સુરત', 5, 'સુદર્શન સેતુ બ્રિજ ખૂબ જ સરસ બન્યો છે. બેટ દ્વારકા જવું હવે ખૂબ સરળ થઈ ગયું છે. શિવરાજપુર બીચનું પાણી ગોવા કરતાં પણ ચોખ્ખું છે!'),
('મીનાબેન જોશી', 'રાજકોટ', 5, 'દ્વારકાની યાત્રા ખૂબ બજેટ-ફ્રેન્ડલી છે. ધર્મશાળામાં ₹૫૦૦-૬૦૦ માં સારો રૂમ મળી ગયો અને ₹૧૨૦ માં ઉત્તમ કાઠિયાવાડી થાળી મળી.');
